  const rows = data_(sh);
  const byId = {}, open = {};
  rows.forEach(function (r, i) {
    if (r[6]) byId[r[6]] = i;
    else { const k = match_(iso_(r[0]), r[1]); (open[k] = open[k] || []).push(i); }
  });
  const adds = [];
