    const gone = {}; dels.forEach(function (d) { gone[d] = true; });
    const cur = data_(sh);
    for (let i = cur.length - 1; i >= 0; i--) if (cur[i][6] && gone[cur[i][6]]) sh.deleteRow(i + 2);
